// 실제 합성 fixture: tests/fixtures/pptx/native-template.pptx (50,079 bytes).
const BASE64 = "";
export function createDemoTemplateFile():File {
  const bytes=Uint8Array.from(atob(BASE64),char=>char.charCodeAt(0));
  return new File([bytes.buffer],"KPC_예시_템플릿.pptx",{type:"application/vnd.openxmlformats-officedocument.presentationml.presentation"});
}
